package com.hbm.client.oreslopper;
import com.hbm.client.model.*;import com.hbm.machine.oreslopper.*;import com.hbm.multiblock.DummyableBlock;import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.ItemDisplayContext;import net.minecraft.world.phys.AABB;
/** Source smooth culled HFR mesh, all original pivots and the lifting bucket's real BASE item. */
public final class OreSlopperRenderer implements BlockEntityRenderer<OreSlopperBlockEntity> {
 static final ResourceLocation MODEL=OreSlopperContent.id("models/machines/ore_slopper.obj"),TEXTURE=OreSlopperContent.id("textures/models/machines/ore_slopper.png");
 public OreSlopperRenderer(BlockEntityRendererProvider.Context context){}
 static void all(PoseStack poses,MultiBufferSource buffers,int light,int overlay){var mesh=LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),MODEL);LegacyObjRenderer.renderAll(mesh,poses,buffers.getBuffer(RenderType.entityCutout(TEXTURE)),light,overlay,0xffffffff,LegacyObjRenderer.Convention.HFR);}
 static void part(WavefrontMesh mesh,String name,PoseStack poses,MultiBufferSource buffers,int light,int overlay){LegacyObjRenderer.renderOnly(mesh,poses,buffers.getBuffer(RenderType.entityCutout(TEXTURE)),light,overlay,0xffffffff,LegacyObjRenderer.Convention.HFR,name);}
 @Override public void render(OreSlopperBlockEntity m,float partial,PoseStack poses,MultiBufferSource buffers,int light,int overlay){int angle=switch(DummyableBlock.facing(m.getBlockState())){case NORTH->0;case SOUTH->180;case EAST->270;default->90;};var mesh=LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),MODEL);LegacyContactShadows.render(m,mesh,new org.joml.Matrix4f().translation(.5F,0,.5F).rotateY((float)Math.toRadians(angle)),poses,buffers);poses.pushPose();poses.translate(.5,0,.5);poses.mulPose(Axis.YP.rotationDegrees(angle));part(mesh,"Base",poses,buffers,light,overlay);
  poses.pushPose();double slide=m.prevSlider+(m.slider-m.prevSlider)*partial;poses.translate(0,0,slide*-3);part(mesh,"Slider",poses,buffers,light,overlay);poses.pushPose();double extend=(m.prevBucket+(m.bucket-m.prevBucket)*partial)*1.5;poses.translate(0,-net.minecraft.util.Mth.clamp(extend-.25,0,1.25),0);part(mesh,"Hydraulics",poses,buffers,light,overlay);poses.translate(0,-net.minecraft.util.Mth.clamp(extend,0,1.25),0);part(mesh,"Bucket",poses,buffers,light,overlay);
  if(m.animation==OreSlopperBlockEntity.Animation.LIFTING){poses.translate(.0625,4.3125,2);poses.mulPose(Axis.YP.rotationDegrees(90));poses.mulPose(Axis.XP.rotationDegrees(-90));poses.scale(1.75F,1.75F,1.75F);var stack=com.hbm.item.bedrockprocessing.ProcessedBedrockItem.make("BASE","LIGHT_METAL",1);Minecraft.getInstance().getItemRenderer().renderStatic(stack,ItemDisplayContext.GROUND,light,overlay,poses,buffers,m.getLevel(),0);}poses.popPose();poses.popPose();
  double blades=m.prevBlades+(m.blades-m.prevBlades)*partial;poses.pushPose();poses.translate(.375,2.75,0);poses.mulPose(Axis.ZP.rotationDegrees((float)blades));poses.translate(-.375,-2.75,0);part(mesh,"BladesLeft",poses,buffers,light,overlay);poses.popPose();poses.pushPose();poses.translate(-.375,2.75,0);poses.mulPose(Axis.ZP.rotationDegrees((float)-blades));poses.translate(.375,-2.75,0);part(mesh,"BladesRight",poses,buffers,light,overlay);poses.popPose();
  double fan=m.prevFan+(m.fan-m.prevFan)*partial;poses.pushPose();poses.translate(0,1.875,-1);poses.mulPose(Axis.XP.rotationDegrees((float)-fan));poses.translate(0,-1.875,1);part(mesh,"Fan",poses,buffers,light,overlay);poses.popPose();poses.popPose();
 }
 @Override public boolean shouldRenderOffScreen(OreSlopperBlockEntity m){return true;}@Override public int getViewDistance(){return 256;}@Override public AABB getRenderBoundingBox(OreSlopperBlockEntity m){var p=m.getBlockPos();return new AABB(p.getX()-3,p.getY(),p.getZ()-3,p.getX()+4,p.getY()+7,p.getZ()+4);}
}
